$read = static function (string $path): array {
    $raw = file_get_contents($path);
    if ($raw === false) throw new RuntimeException('Cannot read ' . $path);
    $value = json_decode($raw, true, 512, JSON_THROW_ON_ERROR);
    return is_array($value) ? array_values(array_filter($value, 'is_array')) : [];
};
$writeJson = static function (string $path, mixed $value): void {
    file_put_contents($path, json_encode($value, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR) . "\n");
};
$append = static function (string $path, array $records) use ($read): void {
    if ($records === []) return;
    $rows = $read($path);
    $rows = array_merge($rows, $records);
    file_put_contents($path, json_encode($rows, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR) . "\n");
};
$replace = static function (string $path, callable $predicate, callable $mutator) use ($read, $writeJson): int {
    $rows = $read($path); $count = 0;
    foreach ($rows as &$row) {
        if ($predicate($row)) { $row = $mutator($row); $count++; }
    }
    unset($row);
    if ($count > 0) $writeJson($path, $rows);
    return $count;
};
