$pathExists = static function (string $from, string $target, array $graph): bool {
    $stack = [$from]; $seen = [];
    while ($stack !== []) {
        $node = array_pop($stack);
        if ($node === $target) return true;
        if (isset($seen[$node])) continue;
        $seen[$node] = true;
        foreach (array_keys($graph[$node] ?? []) as $next) if (!isset($seen[$next])) $stack[] = $next;
    }
    return false;
};
$add = static function (string $concept, string $stem, string $answer, array $wrong, string $explanation, int $depth = 3, string $context = 'PROFESSIONAL', array $safety = [], string $prerequisite = 'ASSUMED_FOUNDATION', string $scenario = 'clinical application', array $misconceptions = [], bool $numeric = false, ?array $calculation = null, ?string $material = null) use (&$questions, $taxonomy, &$prerequisiteGraph, &$prerequisiteCycleFallbacks, $pathExists): void {
    if (!isset($taxonomy[$concept])) throw new RuntimeException('Unknown Nursing concept ' . $concept);
    if (!in_array($depth, [2, 3, 4], true)) throw new RuntimeException('Invalid question depth');
    if (!in_array($context, ['NEUTRAL', 'PROFESSIONAL', 'REGULATORY'], true)) throw new RuntimeException('Invalid context');
    $wrong = array_values(array_map('strval', $wrong));
    if (count($wrong) !== 3 || count(array_unique(array_merge([$answer], $wrong))) !== 4) throw new RuntimeException('Four distinct choices required: ' . $stem);
    if ($safety === []) $safety = [];
    $t = $taxonomy[$concept];
    if (str_starts_with($prerequisite, 'REQUIRED:')) {
        $requiredConcept = substr($prerequisite, strlen('REQUIRED:'));
        if ($requiredConcept === $concept || $pathExists($requiredConcept, $concept, $prerequisiteGraph)) {
            $prerequisiteCycleFallbacks[] = ['primary_concept' => $concept, 'requested_required_concept' => $requiredConcept, 'decision' => 'ASSUMED_FOUNDATION', 'reason' => 'The candidate edge would create a circular global prerequisite graph; the item remains solvable from the primary concept and universal foundations without speculative cross-tagging.'];
            $prerequisite = 'ASSUMED_FOUNDATION';
        } else {
            $prerequisiteGraph[$concept][$requiredConcept] = true;
        }
    }
