$choiceSet = static function (string $answer, array $wrong, int $id): array {
    $choices = array_merge([$answer], $wrong);
    usort($choices, static fn(string $a, string $b): int => strcmp(hash('sha256', $id . '|' . $a), hash('sha256', $id . '|' . $b)));
    return $choices;
};

